228	// classifySession determines if a session is stuck and returns diagnostic info.
229	// Returns nil if the session is healthy.
230	func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
231		// Determine shadow branch info
232		shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
233		refName := plumbing.NewBranchReferenceName(shadowBranch)
234		_, refErr := repo.Reference(refName, true)
235		hasShadowBranch := refErr == nil
236	
237		stuck := func(reason string) *stuckSession {
238			return &stuckSession{
239				State:             state,
240				Reason:            reason,
241				ShadowBranch:      shadowBranch,
242				HasShadowBranch:   hasShadowBranch,
243				CheckpointCount:   state.StepCount,
244				FilesTouchedCount: len(state.FilesTouched),
245			}
246		}
247	
248		// A dead owner is unambiguous and phase-independent, so it is checked ahead
249		// of the phase switch: an agent that quit without firing a session-end hook
250		// leaves the session IDLE just as often as ACTIVE (see State.OwnerExited).
251		// Detected immediately, with no timeout wait. These are normally finalized
252		// up front in runSessionsFix; this covers sessions that couldn't be.
253		if state.OwnerExited() {
254			pid := 0
255			if state.Owner != nil {
256				pid = state.Owner.PID
257			}
258			return stuck(fmt.Sprintf("agent process %d exited (no longer running)", pid))
259		}
260	
261		switch {
262		case state.Phase.IsActive():
263			switch {
264			case !state.IsStuckActive():
265				return nil
266			case state.LastInteractionTime != nil:
267				return stuck(fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute)))
268			default:
269				return stuck(fmt.Sprintf("active, started %s ago with no recorded interaction", now.Sub(state.StartedAt).Truncate(time.Minute)))
270			}
271	
272		case state.Phase == session.PhaseEnded:
273			// Ended sessions are stuck if they have uncondensed data
274			if state.StepCount <= 0 || !hasShadowBranch {
275				return nil
276			}
277			return stuck("ended with uncondensed checkpoint data")
278	
279		default:
280			return nil
281		}
282	}
283	
284	// displayStuckSession prints diagnostic info for a stuck session.
285	func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
286		w := cmd.OutOrStdout()
287	
288		fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
289		fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
290		fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)
291	
292		if ss.State.AgentType != "" {
293			fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
294		}
295	
296		if ss.State.LastInteractionTime != nil {
297			fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
298		}
