func runSessionsFix(cmd *cobra.Command, force bool) error {
	var finalErr error

	// Check 1: Disconnected metadata branches
	metadataErr := checkDisconnectedMetadata(cmd, force)
	if metadataErr != nil {
		fmt.Fprintf(cmd.ErrOrStderr(), "Error: metadata check failed: %v\n", metadataErr)
		finalErr = NewSilentError(fmt.Errorf("metadata check failed: %w", metadataErr))
	}

	fmt.Fprintln(cmd.OutOrStdout())

	ctx := cmd.Context()

	// Agent-specific: Codex hook trust state.
	checkCodexHookTrust(cmd)

	// Agent-specific: Claude Code hook config drift.
	checkClaudeCodeHookDrift(cmd)

	// Where checkpoints land, when the repo's remotes make that ambiguous.
	printCheckpointDestinationNote(ctx, cmd.OutOrStdout(), "Checkpoint destination: REVIEW")

	// Stuck sessions
	// Load all session states
	states, err := strategy.ListSessionStates(ctx)
	if err != nil {
		return fmt.Errorf("failed to list session states: %w", err)
	}

	if len(states) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
		if finalErr != nil {
			return finalErr
		}
		return nil
	}

	// Open repository to check shadow branches (uses worktree-aware helper)
	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}
	defer repo.Close()

	// Finalize any ACTIVE session whose agent process has exited (no SessionStop
	// hook fired). A gone process is unambiguous, so these are condensed on the
	// spot rather than left for the interactive prompt below; the sweep marks
	// them ended in place so classifySession won't re-flag them.
	// Deferred here rather than inside the sweep: the condense and discard paths
	// below log, and this keeps their output in .entire/logs/ instead of on the
	// terminal alongside doctor's own report.
	n, stopLogging := finalizeExitedSessions(ctx, states)
	defer stopLogging()
	if n > 0 {
		fmt.Fprintf(cmd.OutOrStdout(), "Finalized %d exited session(s) (agent process gone).\n\n", n)
	}

	// Identify stuck sessions
	now := time.Now()
	var stuck []stuckSession

	for _, state := range states {
		ss := classifySession(state, repo, now)
		if ss != nil {
			stuck = append(stuck, *ss)
		}
	}

	if len(stuck) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
		if finalErr != nil {
			return finalErr
		}
		return nil
	}

	// Get the current strategy for condense operations
	strat := GetStrategy(ctx)

	fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))

	for _, ss := range stuck {
		displayStuckSession(cmd, ss)

		if force {
			if ss.HasShadowBranch && ss.CheckpointCount > 0 {
				if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
				} else {
					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
				}
			} else {
				// Discard if we can't condense
				if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
				} else {
					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
				}
			}
			continue
		}

		// Interactive: prompt for action
		action, err := promptSessionAction(ss)
		if err != nil {
			if errors.Is(err, huh.ErrUserAborted) {
				return nil
			}
			return fmt.Errorf("failed to get action: %w", err)
		}

		switch action {
		case "condense":
			if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
			} else {
				fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
			}
		case "discard":
			if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
			} else {
				fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
			}
		case "skip":
			fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
		}
	}

	if finalErr != nil {
		return finalErr
	}

	return nil
}

// classifySession determines if a session is stuck and returns diagnostic info.
// Returns nil if the session is healthy.
func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
	// Determine shadow branch info
	shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	refName := plumbing.NewBranchReferenceName(shadowBranch)
	_, refErr := repo.Reference(refName, true)
	hasShadowBranch := refErr == nil

	stuck := func(reason string) *stuckSession {
		return &stuckSession{
			State:             state,
			Reason:            reason,
			ShadowBranch:      shadowBranch,
			HasShadowBranch:   hasShadowBranch,
			CheckpointCount:   state.StepCount,
			FilesTouchedCount: len(state.FilesTouched),
		}
	}

	// A dead owner is unambiguous and phase-independent, so it is checked ahead
	// of the phase switch: an agent that quit without firing a session-end hook
	// leaves the session IDLE just as often as ACTIVE (see State.OwnerExited).
	// Detected immediately, with no timeout wait. These are normally finalized
	// up front in runSessionsFix; this covers sessions that couldn't be.
	if state.OwnerExited() {
		pid := 0
		if state.Owner != nil {
			pid = state.Owner.PID
		}
		return stuck(fmt.Sprintf("agent process %d exited (no longer running)", pid))
	}

	switch {
	case state.Phase.IsActive():
		switch {
		case !state.IsStuckActive():
			return nil
		case state.LastInteractionTime != nil:
			return stuck(fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute)))
		default:
			return stuck(fmt.Sprintf("active, started %s ago with no recorded interaction", now.Sub(state.StartedAt).Truncate(time.Minute)))
		}

	case state.Phase == session.PhaseEnded:
		// Ended sessions are stuck if they have uncondensed data
		if state.StepCount <= 0 || !hasShadowBranch {
			return nil
		}
		return stuck("ended with uncondensed checkpoint data")

	default:
		return nil
	}
}

// displayStuckSession prints diagnostic info for a stuck session.
func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
	w := cmd.OutOrStdout()

	fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
	fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
	fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)

	if ss.State.AgentType != "" {
		fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
	}

	if ss.State.LastInteractionTime != nil {
		fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
	}

package cli

import (
	"context"
	"log/slog"
	"slices"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

// sweepCondenseBudget caps how much wall clock one sweep may spend condensing,
// across all sessions it finalizes.
//
// Marking a session ENDED is a single atomic state-file rename; condensing it
// costs ~120ms at best and seconds for a large transcript. Since sessions stay
// un-finalized for up to StaleSessionThreshold (7 days), a first sweep after
// upgrade can have a large backlog, and the callers here are interactive
// commands — including `entire status --json`, which the MCP entire_status tool
// calls, where nothing prints until the sweep returns.
//
// So every candidate is always marked ended (that is what un-sticks it from
// `entire status`), while condensing runs only while the budget lasts. Skipping
// it is the same fail-open path a failed condense already takes: FullyCondensed
// stays false and PostCommit retries, with `entire doctor` reporting the session
// as "ended with uncondensed checkpoint data" in the meantime. A backlog
// therefore drains over successive invocations instead of stalling one.
const sweepCondenseBudget = time.Second

// finalizeExitedSessions finalizes every non-ended session in states whose
// owning agent process has exited (clean /exit, crash, kill, terminal close,
// reboot) without a SessionStop hook firing — ACTIVE mid-turn, or IDLE because
// the agent finished its turn before quitting. Each is finalized exactly as a
// clean session stop would be: the session-stop transition runs (PhaseEnded +
// EndedAt) and pending work is eagerly condensed, subject to
// sweepCondenseBudget.
//
// It refreshes the matched in-memory states from disk after finalizing — so
// callers can re-filter/re-render without their own reload — and returns the
// number finalized. Each session is best-effort: a failure to mark one ended is
// logged and skipped; a condense failure is logged but the session is still
// counted (PostCommit will retry the condense later).
//
// The second return value tears down the logging this sweep set up, and is the
// caller's to scope: defer it for as long as the caller keeps doing work that
// logs, not just around this call. `entire doctor` is why — it goes on to
// condense and discard sessions, and closing the log file first would put those
// handlers' output back on the user's terminal.
func finalizeExitedSessions(ctx context.Context, states []*session.State) (int, func()) {
	// Nothing to do is overwhelmingly the common case, and returning here keeps
	// the sweep off the logging and store setup below entirely.
	if !slices.ContainsFunc(states, (*session.State).OwnerExited) {
		return 0, func() {}
	}

	// Neither caller (`entire status`, `entire doctor`) initializes logging, so
	// the phase-transition and condense lines below would land on the user's
	// terminal via slog.Default() instead of the log file. The level getter is
	// paired with it exactly as at the other command-level Init sites, or
	// `log_level` in settings would be ignored on this path.
	logging.SetLogLevelGetter(GetLogLevel)
	stopLogging := logging.EnsureInitialized(ctx)

	logCtx := logging.WithComponent(ctx, "session")
	condenseDeadline := time.Now().Add(sweepCondenseBudget)

	var store *session.StateStore // lazily created on first finalize
	finalized := 0
	for _, st := range states {
		if !st.OwnerExited() {
			continue // cheap pre-filter on the (possibly stale) list snapshot
		}

		// Finalize via the same path a clean SessionStop hook would take, but
		// re-validate OwnerExited on the freshly-loaded state under the lock:
		// a turn may have started since the snapshot and replaced the dead
		// owner with a live one, in which case ended is false and we leave it be.
		ended, err := endSessionNow(ctx, nil, st.SessionID, func(s *session.State) bool {
			return s.OwnerExited()
		}, condenseDeadline)
		if err != nil {
			logging.Warn(logCtx, "failed to finalize exited session",
				slog.String("session_id", st.SessionID),
				slog.String("error", err.Error()))
			continue
		}
		if !ended {
			continue
		}

		// Refresh the in-memory snapshot from disk so downstream filtering and
		// doctor classification see the true post-finalize state: ended, and
		// condensed only if the eager condense actually ran and succeeded (it is
		// fail-open and budget-capped, so StepCount/FullyCondensed must not be
		// assumed). Fall back to a minimal ended-marking if the reload fails —
		// enough for the caller's "active" filter to drop it.
		if store == nil {
			if s, serr := session.NewStateStore(ctx); serr == nil {
				store = s
			}
		}
		refreshed := false
		if store != nil {
			if reloaded, lerr := store.Load(ctx, st.SessionID); lerr == nil && reloaded != nil {
				*st = *reloaded
				refreshed = true
			}
		}
		if !refreshed {
			now := time.Now()
			st.Phase = session.PhaseEnded
			st.EndedAt = &now
		}
		finalized++
	}
	return finalized, stopLogging
}

